# Homebrew formula for the Engra CLI. Generated by packaging/release.py in the
# release workflow; do not hand-edit. Release assets live in
# arenberg-engineering/engra-releases.
class Engra < Formula
  desc "AI coding agent and developer assistant for the terminal"
  homepage "https://engra.io"
  # Proprietary software of Arenberg AG, all rights reserved (LICENSE.txt).
  license :cannot_represent

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.13/engra-0.4.13-macos-arm64.tar.gz"
      sha256 "bb6f4ad031261377fb06e884887e0d34d6cdc5e20cd477e19bffec7d798a90d3"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.13/engra-0.4.13-macos-x64.tar.gz"
      sha256 "15368d45f0d80287a595916ec5e6a02b463f9e7d14084f4811072d24d51ab3d1"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.13/engra-0.4.13-linux-arm64.tar.gz"
      sha256 "0d53456800336404a5349d1e7617d948e9031968fe84ca5341773fce1670f69a"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.13/engra-0.4.13-linux-x64.tar.gz"
      sha256 "5ad08030f3cb2e9547ab567bca353a515100575b7ac7ec22a178ad785f265fe3"
    end
  end

  def install
    libexec.install "engra", "_internal"
    bin.install_symlink libexec/"engra"
    prefix.install "LICENSE.txt", "TERMS.md", "THIRD_PARTY_NOTICES.txt"
  end

  def caveats
    <<~EOS
      Sign in with:
        engra login

      Terms of Use: engra legal --terms

      Before uninstalling, run `engra logout` to remove saved credentials from
      the OS keychain. Settings and link state stay in ~/.config/engra (and
      doctor records in ~/.engra); remove them to clear everything.
    EOS
  end

  test do
    assert_equal "engra #{version}", shell_output("#{bin}/engra --version").strip
    assert_match "doctor", shell_output("#{bin}/engra --help")
    assert_match "Arenberg AG", shell_output("#{bin}/engra legal")
  end
end
